import fs from 'node:fs';import path from 'node:path';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
const root=process.cwd(),source=path.join(root,'input/payload/app'),pin=JSON.parse(fs.readFileSync('.github/releases/desktop-channel-input.json','utf8'));
for(const name of ['CSC_LINK','CSC_KEY_PASSWORD','APPLE_ID','APPLE_APP_SPECIFIC_PASSWORD','APPLE_TEAM_ID'])if(!process.env[name])throw Error('Missing signing setting: '+name);
const run=(cmd,args,options={})=>{const r=spawnSync(cmd,args,{stdio:'inherit',...options});if(r.status!==0)throw Error('Packaging command failed: '+cmd);};
const verified=path.join(root,'channel-output/verified');fs.mkdirSync(verified,{recursive:true});const results=[];
for(const version of pin.versions)for(const arch of ['arm64','x64']){
 if(!/^\d+\.\d+\.\d+(?:-beta\.\d+)?$/.test(version))throw Error('Invalid version');
 for(const name of ['package.json','desktop/package.json']){const file=path.join(source,name),p=JSON.parse(fs.readFileSync(file));p.version=version;if(name==='package.json'){p.devDependencies={...(p.devDependencies||{}),electron:'44.4.5'};}fs.writeFileSync(file,JSON.stringify(p,null,2));}
 const notesFile=path.join(source,'desktop/release-notes.json'),notes=JSON.parse(fs.readFileSync(notesFile));notes[0].version=version;notes[0].channel=version.includes('beta')?'beta':'stable';fs.writeFileSync(notesFile,JSON.stringify(notes,null,2));
 run('go',['build','-trimpath','-ldflags','-X main.version='+version,'-o',path.join(source,'bin/lingnest'),'.'],{cwd:path.join(root,'apps/cli'),env:{...process.env,GOOS:'darwin',GOARCH:arch==='x64'?'amd64':'arm64',CGO_ENABLED:'0'}});
 const output=path.join(root,'channel-output',version,arch);const config={appId:'store.inspirai.library.worker',productName:'灵藏',asar:false,electronVersion:'44.4.5',npmRebuild:false,buildDependenciesFromSource:false,directories:{app:source,output},files:['**/*','!desktop/frontend/node_modules/**'],extraResources:[{from:path.join(root,'input/payload/library'),to:'library'}],mac:{target:['zip','dmg'],artifactName:'InspiraiNest-v${version}-macOS-${arch}.${ext}',icon:path.join(source,'desktop/icon.png'),hardenedRuntime:true,entitlements:path.join(source,'desktop/entitlements.mac.plist'),entitlementsInherit:path.join(source,'desktop/entitlements.mac.plist'),forceCodeSigning:true,notarize:true,publish:{provider:'generic',url:'https://library.inspirai.store/updates/macos',useMultipleRangeRequest:false}}};
 const configFile=path.join(root,'channel-output/config.json');fs.writeFileSync(configFile,JSON.stringify(config));run(process.execPath,[path.join(root,'node_modules/electron-builder/out/cli/cli.js'),'--config',configFile,'--mac','zip','dmg','--'+arch,'--publish','never']);
 const bundle=path.join(output,arch==='arm64'?'mac-arm64':'mac','灵藏.app');run('codesign',['--verify','--deep','--strict',bundle]);run('xcrun',['stapler','validate',bundle]);run('spctl',['--assess','--type','execute','--verbose=2',bundle]);
 const info=spawnSync('codesign',['-dv','--verbose=4',bundle],{encoding:'utf8'}).stderr;if(!info.includes('Authority=Developer ID Application:')||!info.includes('TeamIdentifier='+process.env.APPLE_TEAM_ID))throw Error('Public package requires the expected Developer ID team');
 const appVersion=spawnSync('/usr/libexec/PlistBuddy',['-c','Print :CFBundleShortVersionString',path.join(bundle,'Contents/Info.plist')],{encoding:'utf8'}).stdout.trim();if(appVersion!==version)throw Error('Bundle version mismatch');
 for(const name of fs.readdirSync(output).filter(n=>/\.(zip|dmg)(\.blockmap)?$/.test(n))){const file=path.join(output,name),target=path.join(verified,name);fs.copyFileSync(file,target);results.push({version,arch,filename:name,bytes:fs.statSync(target).size,sha256:createHash('sha256').update(fs.readFileSync(target)).digest('hex'),developerId:true,notarized:true});}
}
fs.writeFileSync(path.join(verified,'verified-packages.json'),JSON.stringify({sourceSha256:pin.sha256,commit:process.env.GITHUB_SHA,packages:results},null,2));
